import * as t from 'io-ts';

const Ticket = t.type({ id: t.number, created_at: t.string });
type Ticket = t.TypeOf<typeof Ticket>;

const fromWire = (u: unknown): Ticket =>
  Ticket.decode(u).fold(
    (errors) => { throw new Error(`invalid ticket: ${JSON.stringify(errors)}`); },
    (value) => value,
  );

const toWire = (ticket: Ticket): unknown => Ticket.encode(ticket);

