class Ticket {
  @Expose({ name: 'created_at' })
  @Transform(({ value }) => (value instanceof Date ? value : new Date(value)), { toClassOnly: true })
  @Transform(({ value }) => (value as Date).toISOString(), { toPlainOnly: true })
  createdAt!: Date;

  @Expose() id!: number;
}

